import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { fmt } from "../lib/api";
import { toast } from "sonner";

const BUILDING_IMG =
  "https://www.myboutiquehotel.com/photos/108619/hotel-indigo-warsaw-nowy-wiat-an-ihg-hotel-warsaw-406-97472-600x350.jpg";

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const submit = async (e) => {
    e.preventDefault();
    try {
      await login(email, password);
      toast.success("Welcome back.");
      navigate("/dashboard");
    } catch (err) {
      toast.error(fmt(err.response?.data?.detail) || err.message);
    }
  };

  return (
    <div style={{
      minHeight: "100vh",
      display: "grid",
      gridTemplateColumns: "1fr 1fr",
      marginTop: "-68px", // pull behind sticky navbar
    }}>

      {/* ── LEFT: full-bleed image ── */}
      <div style={{ position: "relative", overflow: "hidden" }}>
        <img
          src={BUILDING_IMG}
          alt="College building"
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            objectPosition: "center",
            display: "block",
          }}
        />
        {/* lighter overlay — rgba opacity ~0.35 so building shows clearly */}
        <div style={{
          position: "absolute",
          inset: 0,
          background: "rgba(10, 48, 38, 0.35)",
        }} />
      </div>

      {/* ── RIGHT: form panel ── */}
      <div style={{
        background: "#f5f2ec",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        padding: "5rem 4rem",
      }}>
        {/* Eyebrow */}
        <div style={{
          fontSize: "0.65rem",
          letterSpacing: "0.22em",
          textTransform: "uppercase",
          color: "#c25942",
          fontWeight: 700,
          marginBottom: "1rem",
          fontFamily: "'EB Garamond', Georgia, serif",
        }}>
          Sign In
        </div>

        {/* Heading */}
        <h1 style={{
          fontFamily: "'Playfair Display', serif",
          fontSize: "clamp(2rem, 3vw, 2.8rem)",
          color: "#0a3026",
          fontWeight: 400,
          lineHeight: 1.2,
          marginBottom: "0.6rem",
        }}>
          Return to the network.
        </h1>

        <p style={{
          color: "#666",
          fontSize: "0.95rem",
          marginBottom: "2.5rem",
          fontFamily: "'EB Garamond', Georgia, serif",
        }}>
          Use your alumnae credentials.
        </p>

        {/* Form */}
        <div onSubmit={submit}>
          {/* Email */}
          <label style={styles.label}>Email</label>
          <input
            type="email"
            required
            placeholder="you@college.edu"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            style={styles.input}
          />

          {/* Password */}
          <label style={styles.label}>Password</label>
          <input
            type="password"
            required
            placeholder="••••••••"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            style={{ ...styles.input, marginBottom: "1.8rem" }}
          />

          {/* Submit */}
          <button
            onClick={submit}
            style={{
              width: "100%",
              background: "#0a3026",
              color: "#fff",
              border: "none",
              padding: "1rem",
              fontSize: "1rem",
              cursor: "pointer",
              fontFamily: "'EB Garamond', Georgia, serif",
              letterSpacing: "0.04em",
            }}
          >
            Sign In
          </button>
        </div>

        {/* Footer link */}
        <p style={{
          marginTop: "1.5rem",
          fontSize: "0.9rem",
          color: "#555",
          fontFamily: "'EB Garamond', Georgia, serif",
        }}>
          New to the network?{" "}
          <Link
            to="/register"
            style={{ color: "#0a3026", textDecoration: "underline" }}
          >
            Request an account
          </Link>
        </p>

        {/* Demo credentials box */}
        <div style={{
          marginTop: "2.5rem",
          padding: "1rem 1.2rem",
          background: "#eae7e0",
          border: "1px solid rgba(0,0,0,0.1)",
          fontSize: "0.8rem",
          color: "#555",
          fontFamily: "'EB Garamond', Georgia, serif",
        }}>
          <div style={{
            fontSize: "0.6rem",
            letterSpacing: "0.18em",
            textTransform: "uppercase",
            color: "#c25942",
            fontWeight: 700,
            marginBottom: "0.4rem",
          }}>Demo</div>
          <div>student1@alumni.edu / student123</div>
          <div>alumni1@alumni.edu / alumni123</div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  label: {
    display: "block",
    fontSize: "0.88rem",
    color: "#2c2c2c",
    marginBottom: "0.4rem",
    fontFamily: "'EB Garamond', Georgia, serif",
    letterSpacing: "0.02em",
  },
  input: {
    width: "100%",
    border: "1px solid rgba(0,0,0,0.18)",
    background: "#fff",
    padding: "0.75rem 1rem",
    fontSize: "0.95rem",
    marginBottom: "1.2rem",
    fontFamily: "'EB Garamond', Georgia, serif",
    color: "#2c2c2c",
    outline: "none",
    boxSizing: "border-box",
  },
};
